package com.bank.spend.service;

import com.bank.spend.dto.CustomerSpend;
import com.bank.spend.model.Customer;
import com.bank.spend.model.Order;
import com.bank.spend.repository.SalesRepository;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

public class SpendService {
    private static final Logger log = Logger.getLogger(SpendService.class.getName());
    private final SalesRepository repo;
    public SpendService(SalesRepository repo) { this.repo = repo; }

    // LEFT JOIN customers -> orders, SUM with COALESCE(...,0).
    public List<CustomerSpend> totalSpentPerCustomer() {
        Map<String, BigDecimal> totals = new HashMap<>();
        for (Order o : repo.allOrders()) {
            totals.merge(o.getCustomerId(), o.getTotalAmount(), BigDecimal::add); // SUM per customer
        }
        List<CustomerSpend> result = new ArrayList<>();
        for (Customer c : repo.allCustomers()) {
            BigDecimal spent = totals.getOrDefault(c.getCustomerId(), BigDecimal.ZERO); // COALESCE(...,0)
            result.add(new CustomerSpend(c.getCustomerId(), c.getName(), spent));
        }
        result.sort((a, b) -> b.getTotalSpent().compareTo(a.getTotalSpent())); // ORDER BY DESC
        log.info(() -> "Computed spend for " + result.size() + " customers");
        return result;
    }
}
