package com.bank.spend;

import com.bank.spend.dto.CustomerSpend;
import com.bank.spend.repository.SalesRepository;
import com.bank.spend.service.SpendService;

public class SpendApplication {
    public static void main(String[] args) {
        SpendService service = new SpendService(new SalesRepository());
        System.out.println("CUSTOMER        TOTAL SPENT");
        for (CustomerSpend s : service.totalSpentPerCustomer()) {
            System.out.printf("%-14s  Rs.%s%n", s.getName(), s.getTotalSpent());
        }
    }
}
